import React from 'react'
import styled, { keyframes } from 'styled-components'
import { colors } from '../styles/common'
import splashImg from '../static/images/NerdensSplash.jpg'

function Splash({ visible }) {
  if (!visible) return null

  return (
    <Overlay role="status" aria-live="polite">
      <Image src={splashImg} alt="Nerdens" />
      <Spinner />
    </Overlay>
  )
}

export default Splash

const pulse = keyframes`
  0% { transform: scale(1); opacity: 0.9; }
  50% { transform: scale(1.05); opacity: 1; }
  100% { transform: scale(1); opacity: 0.9; }
`

const spin = keyframes`
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
`

const Overlay = styled.div`
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  background: linear-gradient(180deg, rgba(0,0,0,0.75) 0%, rgba(0,0,0,0.9) 100%), ${colors.background.dark};
  color: ${colors.text.secondary};
  z-index: 1000;
  animation: ${pulse} 2.2s ease-in-out infinite;
`

const Image = styled.img`
  width: min(420px, 80vw);
  height: auto;
  border-radius: 16px;
  box-shadow: 0 20px 45px rgba(0, 0, 0, 0.35);
  object-fit: contain;
`

const Spinner = styled.div`
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 3px solid rgba(255, 255, 255, 0.15);
  border-top-color: ${colors.white};
  animation: ${spin} 1s linear infinite;
`

const Hint = styled.div`
  font-size: 0.95rem;
  opacity: 0.65;
`
