import styled, { css } from 'styled-components'

// 색상 팔레트
export const colors = {
  primary: '#000000',
  secondary: '#EFEFEF',
  white: '#FFFFFF',
  background: {
    dark: '#000000',
    light: '#FFFFFF'
  },
  text: {
    primary: '#000000',
    secondary: '#EFEFEF',
    light: '#FFFFFF'
  }
}

// 브레이크포인트
export const breakpoints = {
  mobile: '767px',
  tablet: '1023px',
  desktop: '1280px'
}

// 미디어 쿼리 헬퍼
export const media = {
  mobile: (...args) => css`
    @media screen and (max-width: ${breakpoints.mobile}) {
      ${css(...args)}
    }
  `,
  tablet: (...args) => css`
    @media screen and (min-width: ${parseInt(breakpoints.mobile) + 1}px) and (max-width: ${breakpoints.tablet}) {
      ${css(...args)}
    }
  `,
  desktop: (...args) => css`
    @media screen and (min-width: ${parseInt(breakpoints.tablet) + 1}px) {
      ${css(...args)}
    }
  `
}

// 공통 컨테이너 스타일
export const Container = styled.div`
  display: flex;
  height: 100vh;
  align-items: center;
  justify-content: center;
`

// 섹션 타이틀 스타일
export const SectionTitle = styled.h2`
  font-size: 4rem;
  font-weight: 600;
  margin-bottom: 1rem;
  
  ${media.mobile`
    font-size: 2.5rem;
  `}
`

// 섹션 텍스트 스타일
export const SectionText = styled.p`
  font-size: 1.5rem;
  line-height: 1.4;
  
  ${media.mobile`
    font-size: 1.2rem;
  `}
`

// 공통 애니메이션
export const fadeInUp = css`
  animation: fadeInUp 0.8s ease-out forwards;
  
  @keyframes fadeInUp {
    from {
      opacity: 0;
      transform: translateY(30px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
`

export const hover3D = css`
  transform-style: preserve-3d;
  transition: all 0.3s ease;
  
  &:hover {
    transform: translateY(-8px);
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.1);
  }
`
