import React from 'react'
import styled from 'styled-components'
import Slider from 'react-slick'
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';

import ServiceDetail from './ServiceDetail'
import { SERVICES_DATA, SLIDER_SETTINGS } from '../constants/services'

function ServiceSection() {
  const settings = {
    ...SLIDER_SETTINGS,
    arrows: false
  };

  return (
    <ServiceContainer>
      <StyledSlider {...settings}>
        {SERVICES_DATA.map((service) => (
          <ServiceDetail 
            key={service.id}
            serviceId={service.id}
            explanation={service.explanation}
            image={service.image}
            serviceName={service.name}
            appStoreLink={service.appStoreLink}
            googlePlayLink={service.googlePlayLink}
            webLink={service.webLink}
          />
        ))}
      </StyledSlider>
    </ServiceContainer>
  )
}

export default ServiceSection

const ServiceContainer = styled.div`
  display: flex;
  height: 100vh;
  align-items: center;
  justify-content: center;
  background-color: white;
  padding: 2rem;
  
  @media screen and (max-width: 767px) {
    padding: 1rem;
  }
`;

const StyledSlider = styled(Slider)`
  height: 75vh;
  width: 85vw;
  max-width: 1200px;

  .slick-list {
    width: 100%;
    height: 100%;
    border-radius: 24px;
    overflow: hidden;
  }

  .slick-slide {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 4rem 2rem;
    background: white;
    
    @media screen and (max-width: 767px) {
      padding: 2rem 1rem;
    }
  }

  .slick-slide div {
    display: flex;
    flex: 1;
    align-items: center;
    justify-content: center;
  }

  .slick-dots {
    bottom: 30px;
    
    li button:before {
      font-size: 14px;
      color: #ccc;
      opacity: 0.5;
    }
    
    li.slick-active button:before {
      color: #333;
      opacity: 1;
    }
  }

  .slick-track {
    width: 100%;
    height: 100%;
  }
  
  @media screen and (max-width: 767px) {
    height: 70vh;
    width: 95vw;
    
    .slick-dots {
      bottom: 15px;
    }
  }
`;