import { useEffect } from 'react'

const FontLoader = ({ onReady = () => {} }) => {
  useEffect(() => {
    let readyCalled = false

    const callReadyOnce = () => {
      if (readyCalled) return
      readyCalled = true
      onReady()
    }

    const applyClass = (className) => {
      document.body.classList.remove('font-loaded', 'font-fallback')
      if (className) {
        document.body.classList.add(className)
      }
    }

    const safetyTimer = setTimeout(() => {
      applyClass('font-fallback')
      callReadyOnce()
    }, 1200)

    if ('fonts' in document) {
      Promise.all([
        document.fonts.load('1em "KyoboPSW"'),
        document.fonts.load('1em "Pretendard-Regular"'),
        document.fonts.load('1em "HanaHandwriting"'),
        document.fonts.load('1em "Euiyeon"'),
        document.fonts.load('1em "Jua"'),
        document.fonts.load('1em "White1004"')
      ])
        .then(() => {
          clearTimeout(safetyTimer)
          applyClass('font-loaded')
          callReadyOnce()
        })
        .catch((error) => {
          clearTimeout(safetyTimer)
          console.warn('폰트 로딩 실패:', error)
          applyClass('font-fallback')
          callReadyOnce()
        })
    } else {
      clearTimeout(safetyTimer)
      applyClass('font-fallback')
      callReadyOnce()
    }

    return () => clearTimeout(safetyTimer)
  }, [onReady])
  
  return null
}

export default FontLoader
